int factorial(int n) => n <= 1 ? 1 : n * factorial(n - 1);

void main() {
  for (var i = 0; i < 3; i++) {
    print('for $i');
  }

  var j = 0;
  while (j < 3) {
    print('while $j');
    j++;
  }

  do {
    j--;
  } while (j > 0);

  final list = [10, 20, 30];
  for (final v in list) {
    print(v);
  }
  print('5! = ${factorial(5)}');
}

