abstract class Shape {
  double area();
  String describe() => '面积 ${area().toStringAsFixed(2)}';
}

class Circle extends Shape {
  Circle(this.r);
  final double r;

  @override
  double area() => 3.14159 * r * r;
}

class Rect implements Shape {
  Rect(this.w, this.h);
  final double w, h;

  @override
  double area() => w * h;

  @override
  String describe() => '矩形 ${area()}';
}

void main() {
  for (final s in <Shape>[Circle(2), Rect(2, 3)]) {
    print(s.describe());
  }
}

class Box<T> {
