class InsufficientFunds implements Exception {
  InsufficientFunds(this.amount);
  final double amount;

  @override
  String toString() => '余额不足：$amount';
}

void withdraw(double balance, double amount) {
  if (amount > balance) throw InsufficientFunds(amount);
  print('取款成功，余额 ${balance - amount}');
}

void main() {
  try {
    withdraw(100, 150);
  } on InsufficientFunds catch (e) {
    print('捕获：$e');
  } catch (e, st) {
    print('未知错误：$e');
    print(st);
  } finally {
    print('结束');
  }
}

