typedef StrlenNative = IntPtr Function(Pointer<Uint8>);
typedef StrlenDart = int Function(Pointer<Uint8>);

void main() {
  final libc = DynamicLibrary.process();
  final strlen =
      libc.lookupFunction<StrlenNative, StrlenDart>('strlen');

  final ptr = malloc.allocate<Uint8>(6);
  final bytes = ptr.asTypedList(6);
  bytes.setAll(0, 'hello'.codeUnits);
  bytes[5] = 0;

  print('长度：${strlen(ptr)}');
  malloc.free(ptr);
}

abstract class PaymentStrategy {
