void main() {
  final db = sqlite3.open('app.db');
  db.execute('''
    CREATE TABLE IF NOT EXISTS users(
      id INTEGER PRIMARY KEY,
      name TEXT NOT NULL
    )
  ''');

  final stmt = db.prepare('INSERT INTO users(name) VALUES (?)');
