Future<void> main() async {
  final server =
      await HttpServer.bind(InternetAddress.loopbackIPv4, 8080);
  print('监听 http://${server.address.host}:${server.port}');

  await for (final request in server) {
    if (request.uri.path == '/health') {
      request.response
        ..statusCode = HttpStatus.ok
        ..headers.contentType = ContentType.json
        ..write(jsonEncode({'status': 'ok'}));
    } else {
      request.response.statusCode = HttpStatus.notFound;
    }
    await request.response.close();
  }
}

import 'dart:convert';
import 'dart:io';

Future<void> main() async {
  final server =
      await HttpServer.bind(InternetAddress.loopbackIPv4, 8081);
  await for (final req in server) {
    final name = req.uri.queryParameters['name'] ?? '';
    final safe =
        RegExp(r'^[\w\u4e00-\u9fa5]{1,20}$').hasMatch(name);
    final body = safe ? 'Hello, $name' : '参数非法';
    req.response
      ..headers.contentType = ContentType.text
      ..write(body);
    await req.response.close();
  }
}

import 'dart:convert';
import 'dart:io';

Future<void> main(List<String> args) async {
  if (args.isEmpty) {
    stderr.writeln('用法：dart run bin/grep.dart <关键词> [文件]');
    exitCode = 64;
    return;
  }
  final keyword = args[0];
  final path = args.length > 1 ? args[1] : null;
  final lines = path == null
      ? await stdin
          .transform(utf8.decoder)
          .transform(const LineSplitter())
          .toList()
      : await File(path).readAsLines();

  var hits = 0;
  for (final line in lines) {
    if (line.contains(keyword)) {
      hits++;
      print(line);
    }
  }
  stderr.writeln('命中 $hits 行');
}

